INSERT INTO directions (id, slug, name_kz, name_ru, description_kz, description_ru, icon_name, sort_order) VALUES
('c0000001-0000-0000-0000-000000000001', 'it-digital', 'IT және цифрлық технологиялар', 'IT и цифровые технологии', 'Бағдарламалау, ақпараттық қауіпсіздік, деректер талдауы және жасанды интеллект салалары.', 'Сфера разработки программного обеспечения, кибербезопасности, аналитики данных и искусственного интеллекта.', 'Cpu', 1),
('c0000001-0000-0000-0000-000000000002', 'engineering', 'Инженерия және техникалық ғылымдар', 'Инженерия и технические науки', 'Құрылыс, энергетика, механика және робототехника мамандықтары.', 'Строительство, энергетика, робототехника и технологические процессы.', 'Wrench', 2),
('c0000001-0000-0000-0000-000000000003', 'medicine', 'Медицина және денсаулық сақтау', 'Медицина и здравоохранение', 'Жалпы медицина, педиатрия, стоматология және фармацевтикалық бағыттар.', 'Общая медицина, педиатрия, стоматология и фармация.', 'Activity', 3),
('c0000001-0000-0000-0000-000000000004', 'pedagogy', 'Педагогика және білім беру', 'Педагогика и образование', 'Мектепке дейінгі, мектептік және кәсіптік білім беру саласының мұғалімдері.', 'Учителя и преподаватели для школ, колледжей и центров развития.', 'GraduationCap', 4),
('c0000001-0000-0000-0000-000000000005', 'business-law', 'Экономика, бизнес және құқық', 'Экономика, бизнес и право', 'Қаржы, менеджмент, маркетинг және заңтану мамандықтары.', 'Финансы, аудит, менеджмент, маркетинг и юриспруденция.', 'Briefcase', 5),
('c0000001-0000-0000-0000-000000000006', 'creative-arts', 'Өнер, дизайн және медиа', 'Искусство, дизайн и медиа', 'Графикалық дизайн, сәулет, журналистика және креативті индустриялар.', 'Графический дизайн, архитектура, медиакоммуникации и аудиовизуальное производство.', 'Palette', 6);
INSERT INTO institutions (id, slug, name_kz, name_ru, short_name_kz, short_name_ru, institution_type, official_website, address_kz, address_ru, contact_phone, contact_email, dormitory_info_kz, dormitory_info_ru, has_military_department, status, source_id) VALUES
('d0000001-0000-0000-0000-000000000001', 'astana-it-university', 'Astana IT University', 'Astana IT University', 'AITU', 'АИТУ', 'university', 'https://astanait.edu.kz', 'Астана қ., Мәңгілік Ел даңғылы, C1 (EXPO қалашығы)', 'г. Астана, пр. Мангилик Ел, С1 (территория EXPO)', '+7 (7172) 64-57-10', 'admission@astanait.edu.kz', 'Студенттер серіктес жатақханалар мен "Арман қала" кешеніне орналастырылады.', 'Студенты обеспечиваются местами в партнерских общежитиях и ЖК "Арман кала".', true, 'verified', 'a0000001-0000-0000-0000-000000000003'),
('d0000001-0000-0000-0000-000000000002', 'enu-gumilyov', 'Л.Н. Гумилев атындағы Еуразия ұлттық университеті', 'Евразийский национальный университет имени Л.Н. Гумилева', 'ЕҰУ', 'ЕНУ', 'university', 'https://enu.kz', 'Астана қ., Сәтбаев көшесі, 2', 'г. Астана, ул. Сатпаева, 2', '+7 (7172) 70-95-00', 'enu@enu.kz', 'Университеттің 8 студенттік үйі бар. 1-курс студенттеріне басымдық беріледі.', 'В наличии 8 студенческих домов. Приоритет заселения предоставляется первокурсникам.', true, 'verified', 'a0000001-0000-0000-0000-000000000004'),
('d0000001-0000-0000-0000-000000000003', 'astana-medical-university', 'Астана медицина университеті', 'Медицинский университет Астана', 'АМУ', 'МУА', 'university', 'https://amu.edu.kz', 'Астана қ., Бейбітшілік көшесі, 49/А', 'г. Астана, ул. Бейбитшилик, 49/А', '+7 (7172) 53-94-24', 'info@amu.kz', 'Өз жатақханалары мен жалға алынған тұрғын үй кешендері бар.', 'Имеются собственные общежития и арендованные жилые корпуса.', true, 'verified', 'a0000001-0000-0000-0000-000000000005'),
('d0000001-0000-0000-0000-000000000004', 'astana-polytechnic-college', 'Астана политехникалық колледжі', 'Астанинский политехнический колледж', 'АПК', 'АПК', 'college', 'https://polytech.kz', 'Астана қ., Бейбітшілік көшесі, 39', 'г. Астана, ул. Бейбитшилик, 39', '+7 (7172) 31-41-43', 'polytech_astana@mail.ru', 'Колледж аумағында 450 орындық жатақхана қарастырылған.', 'На территории колледжа действует общежитие на 450 мест.', false, 'verified', 'a0000001-0000-0000-0000-000000000006'),
('d0000001-0000-0000-0000-000000000005', 'kazatu-seifullin', 'С. Сейфуллин атындағы Қазақ агротехникалық зерттеу университеті', 'Казахский агротехнический исследовательский университет им. С. Сейфуллина', 'ҚазАТЗУ', 'КазАТИУ', 'university', 'https://kazatu.edu.kz', 'Астана қ., Жеңіс даңғылы, 62', 'г. Астана, пр. Женис, 62', '+7 (7172) 31-75-47', 'rector@kazatu.kz', 'Студенттер қалашығында 7 жатақхана орналасқан.', 'В студенческом городке расположены 7 общежитий.', true, 'verified', 'a0000001-0000-0000-0000-000000000001');
INSERT INTO education_program_groups (id, code, name_kz, name_ru, direction_id, education_level, description_kz, description_ru) VALUES
('e0000001-0000-0000-0000-000000000001', 'B057', 'Ақпараттық қауіпсіздік', 'Информационная безопасность', 'c0000001-0000-0000-0000-000000000001', 'bachelor', 'Кибершабуылдардан қорғау, криптография және желі қауіпсіздігі.', 'Защита цифровых систем, криптография, безопасность сетевых протоколов.'),
('e0000001-0000-0000-0000-000000000002', 'B058', 'Ақпараттық технологиялар', 'Информационные технологии', 'c0000001-0000-0000-0000-000000000001', 'bachelor', 'Бағдарламалық қамтамасыз ету, Data Science және жүйелік инженерия.', 'Разработка ПО, наука о данных, искусственный интеллект и системное администрирование.'),
('e0000001-0000-0000-0000-000000000003', 'B086', 'Жалпы медицина', 'Общая медицина', 'c0000001-0000-0000-0000-000000000003', 'bachelor', 'Клиникалық практика, ауруларды диагностикалау және емдеу.', 'Клиническая практика, диагностика и лечение заболеваний человека.'),
('e0000001-0000-0000-0000-000000000004', 'B042', 'Құқық', 'Право', 'c0000001-0000-0000-0000-000000000005', 'bachelor', 'Азаматтық, қылмыстық және корпоративтік құқық саласының мамандары.', 'Юридическая экспертиза, корпоративное, гражданское и уголовное право.'),
('e0000001-0000-0000-0000-000000000005', 'B018', 'Шетел тілі мұғалімдерін даярлау', 'Подготовка учителей иностранного языка', 'c0000001-0000-0000-0000-000000000004', 'bachelor', 'Ағылшын және өзге шет тілдерін мектептерде оқыту әдістемесі.', 'Преподавание английского и других иностранных языков в школах и колледжах.'),
('e0000001-0000-0000-0000-000000000006', 'COL-0612', 'Есептеу техникасы және бағдарламалық қамтамасыз ету', 'Вычислительная техника и программное обеспечение', 'c0000001-0000-0000-0000-000000000001', 'college', 'Колледжде бағдарламалау, веб-әзірлеу және желілік жабдықтарды баптау.', 'Колледжная программа подготовки веб-разработчиков и техников ПО после 9 и 11 классов.');
