INSERT INTO careers (id, slug, title_kz, title_ru, direction_id, description_kz, description_ru, daily_tasks_kz, daily_tasks_ru, skills_kz, skills_ru, profile_subjects_kz, profile_subjects_ru, employment_outlook_kz, employment_outlook_ru, status, source_id) VALUES
('30000001-0000-0000-0000-000000000001', 'cybersecurity-specialist', 'Киберқауіпсіздік маманы', 'Специалист по кибербезопасности', 'c0000001-0000-0000-0000-000000000001', 'Ақпараттық жүйелерді, дерекқорларды және корпоративтік инфрақұрылымды кибершабуылдар мен деректердің жылыстауынан қорғайтын маман.', 'Специалист, обеспечивающий защиту информационных систем, баз данных и корпоративных сетей от кибератак и утечек данных.', '{"Қауіпсіздік жүйелерін мониторингтеу", "Шабуылдарға қарсы әрекет ету жоспарын құру", "Ақпараттық осалдықтарды талдау (Penetration testing)"}', '{"Мониторинг инцидентов безопасности", "Тестирование на проникновение (пентест)", "Анализ уязвимостей сетевых протоколов"}', '{"Linux", "Желілік протоколдар (TCP/IP)", "Python/Bash", "Криптография"}', '{"Linux", "Сетевые протоколы (TCP/IP)", "Python/Bash", "Криптография"}', 'Математика + Информатика', 'Математика + Информатика', 'Астана мен бүкіл Қазақстан бойынша банктер, мемлекеттік органдар және IT компанияларда сұраныс өте жоғары.', 'Высокий спрос в банковском секторе, квазигосударственных холдингах и ИТ-компаниях столицы.', 'verified', 'a0000001-0000-0000-0000-000000000003'),
('30000001-0000-0000-0000-000000000002', 'software-engineer', 'Бағдарламалық жасақтама инженері', 'Инженер-программист (Software Engineer)', 'c0000001-0000-0000-0000-000000000001', 'Веб-қосымшаларды, мобильді сервистерді және күрделі серверлік архитектураларды жобалап, әзірлейтін маман.', 'Инженер, проектирующий и создающий масштабируемые веб-сервисы, мобильные приложения и облачную архитектуру.', '{"Таза әрі тиімді код жазу", "Дерекқорлар мен API архитектурасын құру", "Кодты тестілеу және жүйені автоматтандыру"}', '{"Проектирование архитектуры сервисов", "Написание чистого и оптимизированного кода", "Интеграция API и работа с базами данных"}', '{"Алгоритмдер", "Go / TypeScript / Python", "PostgreSQL", "Git / Docker"}', '{"Алгоритмы и структуры данных", "Go / TypeScript / Python", "PostgreSQL", "Git / Docker"}', 'Математика + Информатика', 'Математика + Информатика', 'Қазақстандағы ең жылдам өсіп келе жатқан нарықтардың бірі. Қашықтан және жергілікті жұмыс істеу мүмкіндігі мол.', 'Один из наиболее востребованных профилей в Астане с возможностью работы в резидентах Astana Hub.', 'verified', 'a0000001-0000-0000-0000-000000000003'),
('30000001-0000-0000-0000-000000000003', 'general-practitioner-doctor', 'Жалпы практика дәрігері', 'Врач общей практики (ВОП)', 'c0000001-0000-0000-0000-000000000003', 'Науқастардың денсаулығын бақылайтын, алғашқы медициналық-санитариялық көмек көрсететін және аурулардың алдын алатын білікті маман.', 'Врач первичного звена, осуществляющий диагностику, профилактику и базовое лечение распространенных заболеваний.', '{"Пациенттерді қабылдау және тексеру", "Диагноз қою және емдеу жоспарын тағайындау", "Профилактикалық тексерулер өткізу"}', '{"Прием и обследование пациентов", "Постановка первичного диагноза", "Назначение лабораторных исследований и терапии"}', '{"Клиникалық диагностика", "Фармакология негіздері", "Шұғыл көмек көрсету", "Эмпатия және қарым-қатынас"}', '{"Клиническая диагностика", "Основы фармакотерапии", "Неотложная помощь", "Коммуникация с пациентами"}', 'Биология + Химия', 'Биология + Химия', 'Астана қаласының емханалары мен ауруханаларында мемлекеттік басым сұранысқа ие (әкім гранттары тұрақты бөлінеді).', 'Приоритетная профессия для столичной системы здравоохранения с гарантированным трудоустройством.', 'verified', 'a0000001-0000-0000-0000-000000000005');
